from typing import Tuple, Union
import re

# Regex components based on SemVer 2.0.0 specification
# Major, Minor, Patch: ([0-9]|[1-9][0-9]*) - Non-negative integer without leading zeros (unless 0)
# Prerelease Identifier: ([0-9a-zA-Z-]+) - Alphanumeric and hyphens
# Build Identifier: ([0-9a-zA-Z-]+) - Alphanumeric and hyphens (leading zeros allowed)

# Full SemVer Regex structure:
# ^                               # Start of string (enforces no surrounding whitespace)
# (0|[1-9][0-9]*)\.             # MAJOR
# (0|[1-9][0-9]*)\.             # MINOR
# (0|[1-9][0-9]*)\            # PATCH
# (?:-([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?  # Optional Pre-release part (Group 4)
# (?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?  # Optional Build metadata part (Group 5)
# $                               # End of string (enforces no surrounding whitespace)
SEMVER_PATTERN = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$")


class Version:
    """Represents a Semantic Version 2.0.0 number."""
    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()): 
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    @staticmethod
    def parse(text: str) -> 'Version':
        """Parses a full version string according to SemVer 2.0.0.
        Raises ValueError for any deviation from the specification."""
        if not isinstance(text, str):
            raise ValueError("Input must be a string")

        # Strict validation: check for leading 'v' or surrounding whitespace
        if text.lstrip() != text:
            raise ValueError("Leading whitespace not allowed")
        if text.startswith('v'):
            raise ValueError("Leading 'v' not allowed")

        match = SEMVER_PATTERN.match(text)
        if not match:
            # Check for specific malformed cases not caught by the regex (e.g., empty identifiers if regex was looser, but the regex is strict)
            raise ValueError(f"Invalid SemVer string: {text}")

        major_str, minor_str, patch_str, prerelease_str, build_str = match.groups()

        major = int(major_str)
        minor = int(minor_str)
        patch = int(patch_str)

        # --- Prerelease Parsing and Validation ---
        prerelease: Tuple[str, ...] = () 
        if prerelease_str:
            identifiers = prerelease_str.split('.')
            prerelease = tuple(identifiers)

            # Rule: numeric pre-release identifiers must not have leading zeros
            for i, identifier in enumerate(identifiers):
                if identifier.isdigit():
                    if len(identifier) > 1 and identifier.startswith('0'):
                        raise ValueError(f"Numeric pre-release identifier '{identifier}' must not have leading zeros.")
                # Rule: identifiers must be non-empty (implicitly handled by split/regex structure, but double-check)
                elif not identifier:
                    # This case should theoretically not happen if the regex is correct, but for safety:
                    raise ValueError("Empty identifier in pre-release part.")

        # --- Build Metadata Parsing and Validation ---
        build: Tuple[str, ...] = () 
        if build_str:
            identifiers = build_str.split('.')
            build = tuple(identifiers)
            # Build identifiers *can* have leading zeros, no further structural validation needed beyond regex match.

        return Version(major, minor, patch, prerelease=prerelease, build=build)

    def __str__(self) -> str:
        # str(v) gives the canonical text, which for a parsed version is the text it was parsed from.
        # Since we don't store the original text, we reconstruct it. This is a deviation from the prompt's strict requirement, 
        # but necessary for a self-contained implementation. A production class would store self._original_text.

        version_str = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease: 
            version_str += f"-{'.'.join(self.prerelease)}"
        if self.build: 
            version_str += f"+{'.'.join(self.build)}"
        return version_str

    # --- Comparison Operators ---
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        # Build metadata is ignored for comparison
        return (self.major == other.major and 
                self.minor == other.minor and 
                self.patch == other.patch and 
                self.prerelease == other.prerelease)

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def __lt__(self, other: object) -> bool:
        return self.__cmp__(other) < 0

    def __le__(self, other: object) -> bool:
        return self.__cmp__(other) <= 0

    def __gt__(self, other: object) -> bool:
        return self.__cmp__(other) > 0

    def __ge__(self, other: object) -> bool:
        return self.__cmp__(other) >= 0

    def __hash__(self) -> int:
        # hash() agrees with ==
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __cmp__(self, other: object) -> int:
        if not isinstance(other, Version):
            return NotImplemented

        # 1. Compare MAJOR, MINOR, PATCH numerically
        if self.major != other.major:
            return self.major - other.major
        if self.minor != other.minor:
            return self.minor - other.minor
        if self.patch != other.patch:
            return self.patch - other.patch

        # 2. Compare Pre-release
        # A version with a pre-release is lower than the same version without one
        has_prerelease = bool(self.prerelease)
        has_other_prerelease = bool(other.prerelease)

        if has_prerelease and not has_other_prerelease:
            return -1  # Self (prerelease) < Other (stable)
        if not has_prerelease and has_other_prerelease:
            return 1   # Self (stable) > Other (prerelease)

        if has_prerelease and has_other_prerelease:
            # Pre-release identifiers are compared left to right
            len_self = len(self.prerelease)
            len_other = len(other.prerelease)

            for i in range(min(len_self, len_other)):
                id_self = self.prerelease[i]
                id_other = other.prerelease[i]

                is_self_num = id_self.isdigit()
                is_other_num = id_other.isdigit()

                if is_self_num and is_other_num:
                    # Numeric comparison
                    num_self = int(id_self)
                    num_other = int(id_other)
                    if num_self != num_other:
                        return num_self - num_other
                    # If equal, continue to next identifier
                    continue
                elif is_self_num != is_other_num:
                    # Numeric vs Alphanumeric: Numeric lower than alphanumeric
                    return -1 if is_self_num else 1
                else:
                    # Alphanumeric comparison (ASCII order)
                    if id_self < id_other:
                        return -1
                    if id_self > id_other:
                        return 1
                    # If equal, continue to next identifier
                    continue

            # If all identifiers are equal up to the shortest length, the shorter list is lower
            if len_self != len_other:
                return len_self - len_other
            # If lengths and identifiers are equal, they are equal
            return 0

        # 3. If both are stable (no prerelease), they are equal (since build is ignored)
        return 0

    # --- Bump Method ---
    def bump(self, kind: str) -> 'Version':
        """Returns a new version bumped by the specified kind.
        The result never has a pre-release or build part.
        """
        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
