def search_rotated(a: list[int], x: int) -> int:
    """
    Finds the index of x in a rotated sorted list of distinct values.
    Returns the index of x, or -1 if not found. O(log n) time complexity.
    """
    if not a:
        return -1

    low, high = 0, len(a) - 1

    while low <= high:
        mid = low + (high - low) // 2

        if a[mid] == x:
            return mid

        # Check if the left half is sorted (i.e., no rotation break in [low..mid])
        if a[low] <= a[mid]:
            # Left half is sorted
            if a[low] <= x < a[mid]:
                # x must be in the sorted left half
                high = mid - 1
            else:
                # x must be in the unsorted right half
                low = mid + 1
        else:
            # Right half must be sorted (i.e., rotation break in [low..mid])
            if a[mid] < x <= a[high]:
                # x must be in the sorted right half
                low = mid + 1
            else:
                # x must be in the unsorted left half
                high = mid - 1

    return -1

