## EmitError

class EmitError(Exception):
    """Custom exception raised when listeners in an event emitter raise exceptions."""
    def __init__(self, errors=None):
        self.errors = errors if errors is not None else []
        super().__init__()

class EmitError(Exception):
    """Raised when listeners in Emitter raise exceptions."""
    def __init__(self, errors: List[Tuple[Callable, Exception]]):
        self.errors = errors
        super().__init__("One or more listeners raised an exception during emission.")

class Emitter:
    """A simple synchronous event emitter."""
    def __init__(self):
        # Maps event name to a list of registration objects/dicts.
        # Each dict stores: 'listener', 'type' ('on' or 'once'), and 'called' (for 'once').
        self._listeners: Dict[str, List[Dict[str, Any]]] = {}

    def on(self, event: str, listener: callable) -> callable:
        """Register a listener for an event."""
        if event not in self._listeners:
            self._listeners[event] = []
        registration = {
            'listener': listener,
            'type': 'on',
            'called': False
        }
        self._listeners[event].append(registration)
        return listener

    def once(self, event: str, listener: callable) -> callable:
        """Register a listener that will be called only once."""
        if event not in self._listeners:
            self._listeners[event] = []
        registration = {
            'listener': listener,
            'type': 'once',
            'called': False
        }
        self._listeners[event].append(registration)
        return listener

    def off(self, event: str, listener: callable | None = None) -> int:
        """Remove the earliest remaining registration of listener for event."""
        if event not in self._listeners:
            return 0

        listeners_to_remove_indices = []
        if listener is None:
            # Remove all registrations for this event
            listeners_to_remove_indices = list(range(len(self._listeners[event])))
        else:
            # Remove the first matching listener
            for i, reg in enumerate(self._listeners[event]):
                if reg['listener'] == listener:
                    listeners_to_remove_indices.append(i)
                    break

        removed_count = len(listeners_to_remove_indices)
        if removed_count > 0:
            # Remove indices in reverse order to maintain correct indexing
            for i in sorted(listeners_to_remove_indices, reverse=True):
                del self._listeners[event][i]

        return removed_count

    def listeners(self, event: str) -> List[callable]:
        """Return the registered listeners for event in order."""
        if event not in self._listeners:
            return []
        # Extract only the callable part
        return [reg['listener'] for reg in self._listeners[event]]
    # --- Implementation of listeners() ---
    def listeners(self, event: Any) -> List[Callable]:
        """Returns the registered listeners for an event in registration order."""
        if event not in self._listeners:
            return []
        # Extract only the callable part, creating a shallow copy of references
        return [reg['listener'] for reg in self._listeners[event]]
        # 2. Create a fixed list of listeners to process.
        listeners_to_call = list(self._listeners[event])
        call_count = 0
        failures: List[Tuple[Callable, Exception]] = []

        # 3. Iterate, calling each listener; increment call count. Use try/except block for each call;
        # if exception occurs, record (listener, exception) and continue.
        for listener in listeners_to_call:
            try:
                listener(*args, **kwargs)
                call_count += 1
            except Exception as e:
                failures.append((listener, e))
                call_count += 1 # Still counts as a call made

        # 4. After loop, if any exceptions were recorded, raise EmitError containing all recorded failures.
