from dataclasses import dataclass, field
from datetime import date
from typing import Callable, Optional, List
from collections import deque

# Assuming these are imported from sibling/parent modules
from library.catalog import Catalog, Member, Book
from library.fines import POLICY, due_date, fine_for, HOLD_PICKUP_DAYS

# --- Exceptions ---

class LoanError(Exception):
    """Base exception for loan system errors."""
    pass

class Blocked(LoanError):
    """Raised when member has outstanding fines and cannot check out."""
    pass

class DuplicateLoan(LoanError):
    """Raised when member already has the ISBN on loan or a hold on it."""
    pass

class LimitReached(LoanError):
    """Raised when member has reached max_loans."""
    pass

class NotAvailable(LoanError):
    """Raised when no copies are available for loan."""
    pass

class RenewalRefused(LoanError):
    """Raised when renewal is denied due to various conditions."""
    pass

# --- Data Classes ---

@dataclass(frozen=True)
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: Optional[date] = None
    fine: int = 0

# --- Library Class ---

class Library:
    """The core lending system managing loans, holds, and balances."""
    def __init__(self, catalog: Catalog, clock: Callable[[], date]):
        self.catalog = catalog
        self.clock = clock
        # State management
        self._loans: dict[int, Loan] = {}
        self._next_loan_id: int = 1
        self._member_balances: dict[str, int] = {}

        # Holds management: {isbn: deque[member_id]} for waiting holds
        self._waiting_holds: dict[str, deque[str]] = {}
        # Ready holds: {member_id: (isbn, deadline)} for ready holds
        self._ready_holds: dict[str, tuple[str, date]] = {}
        # Hold tracking: {member_id: {isbn: 'waiting' | 'ready'}} 
        self._member_hold_status: dict[str, dict[str, str]] = {}

        # Initialize member balances based on catalog members
        for member in catalog.members.values():
            self._member_balances[member.member_id] = 0

    def _apply_expirations(self, today: date):
        """Applies hold expiry logic for the start of the day."""
        expired_holds = []
        ready_holds_to_check = list(self._ready_holds.items())

        for member_id, (isbn, deadline) in ready_holds_to_check:
            if deadline < today:
                expired_holds.append((member_id, isbn))

        for member_id, isbn in expired_holds:
            # 1. Remove ready hold
            del self._ready_holds[member_id]

            # 2. Check for waiting holds for this ISBN
            if isbn in self._waiting_holds and self._waiting_holds[isbn]:
                # Set aside copy for the earliest waiting hold
                next_waiter_id = self._waiting_holds[isbn].popleft()
                # Make it ready with a new deadline
                new_deadline = due_date(today, HOLD_PICKUP_DAYS)
                self._ready_holds[next_waiter_id] = (isbn, new_deadline)

                # Update member hold status
                if next_waiter_id not in self._member_hold_status:
                     self._member_hold_status[next_waiter_id] = {}
                self._member_hold_status[next_waiter_id][isbn] = 'ready'
            else:
                # No waiting hold, copy becomes available (no explicit state change needed here other than removal from ready_holds)
                pass

    def available(self, isbn: str) -> int:
        """Calculates the number of physically available copies of an ISBN."""
        book = self.catalog.book(isbn)
        total_copies = book.copies

        active_loans = sum(1 for loan in self._loans.values() if loan.isbn == isbn and loan.returned is None)

        # Count copies set aside for ready holds
        ready_holds_count = sum(1 for _, (isbn_hold, _) in self._ready_holds.items() if isbn_hold == isbn)

        return total_copies - active_loans - ready_holds_count

    # --- Core Methods ---

    def checkout(self, member_id: str, isbn: str) -> Loan:
        today = self.clock()

        # 1. Blocked check
        balance = self._member_balances[member_id]
        if balance > 0:
            raise Blocked(f"Member {member_id} has an outstanding balance of {balance} cents.")

        # 2. DuplicateLoan check (Active loan)
        active_loans = [loan for loan in self._loans.values() if loan.member_id == member_id and loan.returned is None]
        if any(loan.isbn == isbn for loan in active_loans):
            raise DuplicateLoan("Member already has this ISBN on loan.")

        # 3. LimitReached check
        member = self.catalog.member(member_id)
        max_loans = POLICY[member.kind].max_loans
        if len(active_loans) >= max_loans:
            raise LimitReached(f"Member has reached the loan limit of {max_loans}.")

        # 4. Availability and Hold usage
        available_count = self.available(isbn)

        if available_count > 0:
            # Check for ready hold
            if member_id in self._ready_holds and self._ready_holds[member_id][0] == isbn:
                # Use set-aside copy, remove ready hold
                del self._ready_holds[member_id]
                del self._member_hold_status[member_id][isbn]
            elif available_count > 0:
                # No ready hold, just use available copy
                pass
            else:
                # This path should ideally not be hit if available_count > 0, but acts as fallback
                raise NotAvailable(f"No copies available for {isbn}.")

        else:
            # If available count is 0, we check for a waiting hold which implies a copy should be set aside.
            # However, the logic dictates checkout fails if available(isbn) == 0, unless it's using a ready hold.
            # Since we checked for a ready hold above, if available_count <= 0 here, it means no copy can be given.
            raise NotAvailable(f"No copies available for {isbn}.")

        # Successful checkout
        loan_id = self._next_loan_id
        self._next_loan_id += 1

        # Calculate due date
        member_kind = self.catalog.member(member_id).kind
        loan_days = POLICY[member_kind].loan_days
        due = due_date(today, loan_days)

        new_loan = Loan(loan_id=loan_id, member_id=member_id, isbn=isbn, start=today, due=due)
        self._loans[loan_id] = new_loan

        # Remove waiting hold if present
        if isbn in self._waiting_holds and member_id in self._waiting_holds[isbn]:
            self._waiting_holds[isbn].remove(member_id)
            if member_id not in self._member_hold_status:
                self._member_hold_status[member_id] = {}
            del self._member_hold_status[member_id][isbn]

        return new_loan

    def place_hold(self, member_id: str, isbn: str) -> int:
        today = self.clock()

        member = self.catalog.member(member_id)
        # Check if already on loan or has a hold
        if any(l.member_id == member_id and l.isbn == isbn and l.returned is None for l in self._loans.values()):
            raise DuplicateLoan("Member already has this ISBN on loan.")
        if member_id in self._member_hold_status and isbn in self._member_hold_status[member_id]:
            raise DuplicateLoan("Member already has a hold on this ISBN.")

        available_count = self.available(isbn)
        if available_count > 0:
            raise LoanError(f"Cannot place hold: {available_count} copies are currently available.")

        # Add to waiting queue
        if isbn not in self._waiting_holds:
            self._waiting_holds[isbn] = deque()

        self._waiting_holds[isbn].append(member_id)

        # Determine position (1-based)
        position = len(self._waiting_holds[isbn])

        # Update member hold status
        if member_id not in self._member_hold_status:
             self._member_hold_status[member_id] = {}
        self._member_hold_status[member_id][isbn] = 'waiting'

        return position

    def cancel_hold(self, member_id: str, isbn: str) -> None:
        today = self.clock()

        if member_id not in self._member_hold_status or isbn not in self._member_hold_status[member_id]:
            raise KeyError(f"Member {member_id} does not have a hold on {isbn}.")

        status = self._member_hold_status[member_id][isbn]

        if status == 'waiting':
            # Remove from waiting queue
            if isbn in self._waiting_holds:
                try:
                    self._waiting_holds[isbn].remove(member_id)
                except ValueError:
                    # Should not happen if _member_hold_status is correct
                    pass
        elif status == 'ready':
            # Ready hold cancellation acts like expiry
            if member_id in self._ready_holds and self._ready_holds[member_id][0] == isbn:
                del self._ready_holds[member_id]

        # Remove status regardless of type
        del self._member_hold_status[member_id][isbn]

        # Pass copy forward if it was a ready hold cancellation or an expiry
        # If it was a waiting hold cancellation, nothing happens to the physical copy, so we only process the ready/expiry path.
        if status == 'ready':
            if isbn in self._waiting_holds and self._waiting_holds[isbn]:
                next_waiter_id = self._waiting_holds[isbn].popleft()
                new_deadline = due_date(today, HOLD_PICKUP_DAYS)
                self._ready_holds[next_waiter_id] = (isbn, new_deadline)

                if next_waiter_id not in self._member_hold_status:
                     self._member_hold_status[next_waiter_id] = {}
                self._member_hold_status[next_waiter_id][isbn] = 'ready'
        elif status == 'waiting':
            # Cancelling a waiting hold does not advance the queue/release a copy.
            pass

    def holds(self, isbn: str) -> list[str]:
        if isbn not in self._waiting_holds:
            return []
        return list(self._waiting_holds[isbn])

    def hold_status(self, member_id: str, isbn: str) -> tuple[str, date] | tuple[str, int]:
        if member_id not in self._member_hold_status or isbn not in self._member_hold_status[member_id]:
            raise KeyError(f"No hold found for member {member_id} on ISBN {isbn}.")

        status_type = self._member_hold_status[member_id][isbn]

        if status_type == 'ready':
            _, deadline = self._ready_holds[member_id]
            return ('ready', deadline)
        elif status_type == 'waiting':
            if isbn in self._waiting_holds:
                # 1-based position
                try:
                    position = self._waiting_holds[isbn].index(member_id) + 1
                    return ('waiting', position)
                except ValueError:
                    # Should be impossible if state is consistent
                    raise KeyError("Internal hold state inconsistency.")
            else:
                 # Should not happen if status is 'waiting'
                 raise KeyError("Internal hold state inconsistency.")

        # Should be unreachable
        raise RuntimeError("Unknown hold status.")

    def renew(self, loan_id: int) -> date:
        loan = self._loans.get(loan_id)
        if not loan:
            raise KeyError(f"Loan ID {loan_id} not found.")

        if loan.returned is not None:
            raise LoanError("Cannot renew a returned loan.")

        # 1. Check if overdue
        today = self.clock()
        if loan.due < today:
            raise RenewalRefused("Loan is already overdue.")

        # 2. Check for holds (waiting or ready)
        if loan.isbn in self._waiting_holds or self._ready_holds:
             # Check if any hold exists for this ISBN
             if any(self._ready_holds.values()).any(lambda x: x[0] == loan.isbn) or 
                any(isbn in self._waiting_holds for isbn in [loan.isbn]):
                raise RenewalRefused("Cannot renew loan because there is a hold on this ISBN.")

        # 3. Check renewal limit
        member = self.catalog.member(loan.member_id)
        max_renewals = POLICY[member.kind].renewals
        if loan.renewals >= max_renewals:
            raise RenewalRefused(f"Loan has reached the maximum renewal limit of {max_renewals}.")

        # Success: Renew
        new_due = due_date(loan.due, POLICY[member.kind].loan_days)
        new_loan = loan.__class__(**loan.__dict__, renewals=loan.renewals + 1, due=new_due)
        self._loans[loan_id] = new_loan
        return new_due

    def checkin(self, loan_id: int) -> int:
        loan = self._loans.get(loan_id)
        if not loan:
            raise KeyError(f"Loan ID {loan_id} not found.")
        if loan.returned is not None:
            raise LoanError("Loan has already been returned.")

        today = self.clock()
        member_id = loan.member_id
        isbn = loan.isbn

        # 1. Compute fine
        fine_amount = fine_for(member_id, loan.due, today) # Note: fine_for expects kind, but we use member_id for lookup
        # Assuming fine_for can take member_id or that we extract kind here.
        # Re-reading prompt: fine_for(kind: str, due: date, returned: date) -> int
        member = self.catalog.member(member_id)
        fine_amount = fine_for(member.kind, loan.due, today)

        # 2. Update loan record
        returned_loan = loan.__class__(**loan.__dict__, returned=today, fine=fine_amount)
        self._loans[loan_id] = returned_loan

        # 3. Update member balance
        self._member_balances[member_id] += fine_amount

        # 4. Set aside copy for waiting hold
        if isbn in self._waiting_holds and self._waiting_holds[isbn]:
            next_waiter_id = self._waiting_holds[isbn].popleft()
            new_deadline = due_date(today, HOLD_PICKUP_DAYS)
            self._ready_holds[next_waiter_id] = (isbn, new_deadline)

            # Update member hold status for the new ready hold
            if next_waiter_id not in self._member_hold_status:
                 self._member_hold_status[next_waiter_id] = {}
            self._member_hold_status[next_waiter_id][isbn] = 'ready'

        # 5. Return fine
        return fine_amount

    def accrued_fine(self, loan_id: int) -> int:
        loan = self._loans.get(loan_id)
        if not loan or loan.returned is None:
            raise KeyError("Loan not found or not yet returned.")
        return loan.fine

    def balance(self, member_id: str) -> int:
        return self._member_balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        current_balance = self.balance(member_id)
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")
        if amount > current_balance:
            raise ValueError("Payment amount exceeds current balance.")

        self._member_balances[member_id] -= amount
        return self._member_balances[member_id]

    def loans(self, member_id: str) -> List[Loan]:
        active_loans = [l for l in self._loans.values() 
                        if l.member_id == member_id and l.returned is None]

        # Sort by due date, then loan id
        return sorted(active_loans, key=lambda l: (l.due, l.loan_id))

    def overdue(self) -> List[Loan]:
        today = self.clock()
        overdue_loans = [l for l in self._loans.values() 
                          if l.returned is None and l.due < today]

        # Sort by due date, then loan id
        return sorted(overdue_loans, key=lambda l: (l.due, l.loan_id))

# NOTE on fine_for usage in checkin: The original prompt implies fine_for uses 'kind'.
# Since we are in loans.py and only have member_id, we must retrieve the kind from the Catalog
# and pass it to fine_for.
# I've adjusted the checkin method to reflect this dependency on Catalog/Member lookup.
