from dataclasses import dataclass
from typing import List
from library.fines import POLICY
from datetime import date

@dataclass(frozen=True)
class Book:
    isbn: str
    title: str
    author: str
    copies: int

@dataclass(frozen=True)
class Member:
    member_id: str
    name: str
    kind: str

class Catalog:
    """Manages the collection of books and registered members."""
    def __init__(self):
        self.books: dict[str, Book] = {}
        self.members: dict[str, Member] = {}

    def add_book(self, isbn: str, title: str, author: str, copies: int = 1) -> Book:
        if isbn in self.books:
            raise ValueError(f"Book with ISBN {isbn} already exists.")
        if copies < 1:
            raise ValueError("Copies must be at least 1.")

        new_book = Book(isbn=isbn, title=title, author=author, copies=copies)
        self.books[isbn] = new_book
        return new_book

    def add_copies(self, isbn: str, n: int) -> int:
        if isbn not in self.books:
            raise KeyError(f"ISBN {isbn} not found in catalog.")
        if n < 1:
            raise ValueError("Number of copies must be at least 1.")

        book = self.books[isbn]
        new_copies = book.copies + n

        # Update the book in the dictionary with the new count
        # Since Book is frozen, we create a new instance to replace it
        self.books[isbn] = Book(isbn=isbn, title=book.title, author=book.author, copies=new_copies)
        return new_copies

    def add_member(self, member_id: str, name: str, kind: str = 'standard') -> Member:
        if member_id in self.members:
            raise ValueError(f"Member with ID {member_id} already exists.")
        if kind not in POLICY:
            raise ValueError(f"Member kind '{kind}' is not a recognized policy kind.")

        new_member = Member(member_id=member_id, name=name, kind=kind)
        self.members[member_id] = new_member
        return new_member

    def book(self, isbn: str) -> Book:
        if isbn not in self.books:
            raise KeyError(f"Book with ISBN {isbn} not found.")
        return self.books[isbn]

    def member(self, member_id: str) -> Member:
        if member_id not in self.members:
            raise KeyError(f"Member with ID {member_id} not found.")
        return self.members[member_id]

    def search(self, text: str) -> List[Book]:
        text_lower = text.lower()
        results: List[Book] = []
        for book in self.books.values():
            if text_lower in book.title.lower() or text_lower in book.author.lower():
                results.append(book)

        # Sort by title then isbn
        results.sort(key=lambda b: (b.title.lower(), b.isbn))
        return results

