# --- Exceptions ---

class LoanError(Exception):
    """Base exception for loan system errors."""
    pass

class Blocked(LoanError):
    """Raised when member has outstanding fines and cannot check out."""
    pass

class DuplicateLoan(LoanError):
    """Raised when member already has the ISBN on loan or a hold on it."""
    pass

class LimitReached(LoanError):
    """Raised when member has reached max_loans."""
    pass

class NotAvailable(LoanError):
    """Raised when no copies are available for loan."""
    pass

class RenewalRefused(LoanError):
    """Raised when renewal is denied due to various conditions."""
    pass

# --- Data Classes ---

@dataclass(frozen=True)
class Loan:
    loan_id: int
    member_id: str
    isbn: str
    start: date
    due: date
    renewals: int = 0
    returned: Optional[date] = None
    fine: int = 0

