        for member in catalog.members.values():
            self._member_balances[member.member_id] = 0

    def _apply_expirations(self, today: date):
        """Applies hold expiry logic for the start of the day."""
        expired_holds = []
        ready_holds_to_check = list(self._ready_holds.items())

        for member_id, (isbn, deadline) in ready_holds_to_check:
            if deadline < today:
                expired_holds.append((member_id, isbn))

        for member_id, isbn in expired_holds:
            # 1. Remove ready hold
            del self._ready_holds[member_id]

            # 2. Check for waiting holds for this ISBN
            if isbn in self._waiting_holds and self._waiting_holds[isbn]:
                # Set aside copy for the earliest waiting hold
                next_waiter_id = self._waiting_holds[isbn].popleft()
                # Make it ready with a new deadline
                new_deadline = due_date(today, HOLD_PICKUP_DAYS)
                self._ready_holds[next_waiter_id] = (isbn, new_deadline)

                # Update member hold status
                if next_waiter_id not in self._member_hold_status:
                     self._member_hold_status[next_waiter_id] = {}
                self._member_hold_status[next_waiter_id][isbn] = 'ready'
            else:
