        """Calculates the number of physically available copies of an ISBN."""
        book = self.catalog.book(isbn)
        total_copies = book.copies

        active_loans = sum(1 for loan in self._loans.values() if loan.isbn == isbn and loan.returned is None)

        # Count copies set aside for ready holds
        ready_holds_count = sum(1 for _, (isbn_hold, _) in self._ready_holds.items() if isbn_hold == isbn)

        return total_copies - active_loans - ready_holds_count

