        if loan.isbn in self._waiting_holds or self._ready_holds:
             # Check if any hold exists for this ISBN
             if any(self._ready_holds.values()).any(lambda x: x[0] == loan.isbn) or 
                any(isbn in self._waiting_holds for isbn in [loan.isbn]):
                raise RenewalRefused("Cannot renew loan because there is a hold on this ISBN.")

        # 3. Check renewal limit
        member = self.catalog.member(loan.member_id)
        max_renewals = POLICY[member.kind].renewals
        if loan.renewals >= max_renewals:
            raise RenewalRefused(f"Loan has reached the maximum renewal limit of {max_renewals}.")

        # Success: Renew
        new_due = due_date(loan.due, POLICY[member.kind].loan_days)
        new_loan = loan.__class__(**loan.__dict__, renewals=loan.renewals + 1, due=new_due)
        self._loans[loan_id] = new_loan
        return new_due

    def checkin(self, loan_id: int) -> int:
        loan = self._loans.get(loan_id)
        if not loan:
            raise KeyError(f"Loan ID {loan_id} not found.")
        if loan.returned is not None:
            raise LoanError("Loan has already been returned.")

        today = self.clock()
        member_id = loan.member_id
        isbn = loan.isbn

        # 1. Compute fine
        fine_amount = fine_for(member_id, loan.due, today) # Note: fine_for expects kind, but we use member_id for lookup
        # Assuming fine_for can take member_id or that we extract kind here.
        # Re-reading prompt: fine_for(kind: str, due: date, returned: date) -> int
        member = self.catalog.member(member_id)
        fine_amount = fine_for(member.kind, loan.due, today)

        # 2. Update loan record
        returned_loan = loan.__class__(**loan.__dict__, returned=today, fine=fine_amount)
        self._loans[loan_id] = returned_loan

        # 3. Update member balance
        self._member_balances[member_id] += fine_amount

        # 4. Set aside copy for waiting hold
        if isbn in self._waiting_holds and self._waiting_holds[isbn]:
            next_waiter_id = self._waiting_holds[isbn].popleft()
            new_deadline = due_date(today, HOLD_PICKUP_DAYS)
            self._ready_holds[next_waiter_id] = (isbn, new_deadline)

            # Update member hold status for the new ready hold
            if next_waiter_id not in self._member_hold_status:
                 self._member_hold_status[next_waiter_id] = {}
            self._member_hold_status[next_waiter_id][isbn] = 'ready'

        # 5. Return fine
        return fine_amount

    def accrued_fine(self, loan_id: int) -> int:
        loan = self._loans.get(loan_id)
        if not loan or loan.returned is None:
            raise KeyError("Loan not found or not yet returned.")
        return loan.fine

    def balance(self, member_id: str) -> int:
        return self._member_balances.get(member_id, 0)

    def pay(self, member_id: str, amount: int) -> int:
        current_balance = self.balance(member_id)
        if amount <= 0:
            raise ValueError("Payment amount must be positive.")
        if amount > current_balance:
            raise ValueError("Payment amount exceeds current balance.")

        self._member_balances[member_id] -= amount
        return self._member_balances[member_id]

    def loans(self, member_id: str) -> List[Loan]:
        active_loans = [l for l in self._loans.values() 
                        if l.member_id == member_id and l.returned is None]

        # Sort by due date, then loan id
        return sorted(active_loans, key=lambda l: (l.due, l.loan_id))

    def overdue(self) -> List[Loan]:
        today = self.clock()
        overdue_loans = [l for l in self._loans.values() 
                          if l.returned is None and l.due < today]

        # Sort by due date, then loan id
        return sorted(overdue_loans, key=lambda l: (l.due, l.loan_id))

# NOTE on fine_for usage in checkin: The original prompt implies fine_for uses 'kind'.
# Since we are in loans.py and only have member_id, we must retrieve the kind from the Catalog
