        # Rule 3: Error propagation
        if isinstance(operand_val, ErrorValue):
            return operand_val

        # Handle unary signs for numbers and references
        if self.op == "+":
            if isinstance(operand_val, (int, float)): return operand_val
            # If operand is text, unary + yields text
            return operand_val
        elif self.op == "-":
            if isinstance(operand_val, (int, float)): return -operand_val
            # If operand is text, unary - yields text
            return operand_val
        return operand_val # Should not happen

class BinaryOpNode(Node):
    """Represents a binary operation (+, -, *, /)."""
    def __init__(self, left: Node, op: str, right: Node):
        self.left = left
        self.op = op
        self.right = right

    def evaluate(self, lookup: Dict[str, Any]) -> Any:
        left_val = self.left.evaluate(lookup)
        right_val = self.right.evaluate(lookup)

        # Rule 3: Error propagation
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: Text evaluation
        if isinstance(left_val, str) or isinstance(right_val, str):
            # If either is text, the result is #ERROR! (unless one is a reference that returned text)
            # We must check if both are text. If one is a reference returning text, the result is text.
            # Since the grammar implies expressions combine numbers/refs, if a string appears here, it implies #ERROR!
            if isinstance(left_val, str) and not (isinstance(left_val, ErrorValue) and left_val == "#ERROR!"):
                return ERROR_ERROR
            if isinstance(right_val, str) and not (isinstance(right_val, ErrorValue) and right_val == "#ERROR!"):
                return ERROR_ERROR

        # Rule 4: Arithmetic evaluation
        try:
            if self.op == "+":
                return left_val + right_val
            elif self.op == "-":
                return left_val - right_val
            elif self.op == "*":
                return left_val * right_val
            elif self.op == "/":
                if right_val == 0:
                    return ERROR_ERROR
                return left_val / right_val
        except TypeError:
            # Catches addition/subtraction between incompatible types (e.g., int + string that isn't an ErrorValue)
            return ERROR_ERROR

        return ERROR_ERROR

# --- Lexer and Parser Implementation ---

class Token:
    def __init__(self, type: str, value: Any = None):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0

    def skip_whitespace(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def next_token(self) -> Token:
        self.skip_whitespace()
        if self.pos >= len(self.text):
            return Token("EOF")

        char = self.text[self.pos]

        # Operators and Parentheses
        if char in '+-*/()':
            self.pos += 1
            if char in '+-*/':
                return Token(char, char)
            else:
                return Token(char, char)

        # Numbers (Digits and optional decimal point)
        elif char.isdigit() or char == '.':
            start = self.pos
            has_dot = False
            while self.pos < len(self.text) and (self.text[self.pos].isdigit() or self.text[self.pos] == '.'):
                if self.text[self.pos] == '.':
                    if has_dot: raise FormulaError("Multiple decimal points in number")
                    has_dot = True
                self.pos += 1
            value_str = self.text[start:self.pos]
            try:
                if '.' in value_str: self.pos -= 1 # Revert pos for caller to handle correctly
                value = float(value_str)
                if value == int(value): value = int(value)
            except ValueError:
                raise FormulaError(f"Invalid number format: {value_str}")

            self.pos = start + len(value_str)
            return Token("NUMBER", value)

        # References (Letters followed by digits)
        elif char.isalpha():
            start = self.pos
            while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos].isalpha()):
                self.pos += 1
            name = self.text[start:self.pos].upper()

            # Grammar constraint: ref := letters digits
            # Check if it strictly follows letters followed by digits
            if not re.match(r"^[A-Z]+[0-9]+$", name):
                # This catches things like 'A' (letters only) or 'A1B' (mixed)
                raise FormulaError(f"Invalid reference format: {name}")

            # Check row constraints (1 to 999, no leading zeros unless it's '0' which is invalid for row)
            letters_part = re.match(r"([A-Z]+)", name).group(1)
            digits_part = name[len(letters_part):]

            try:
                row = int(digits_part)
                if row < 1 or row > 999:
                    raise FormulaError(f"Reference row out of bounds: {name}")
                if len(digits_part) > 1 and digits_part.startswith('0'):
                    raise FormulaError(f"Reference row cannot have leading zeros: {name}")
            except ValueError:
                # Should not happen if regex above worked, but safety catch
                raise FormulaError(f"Invalid reference digits: {name}")

            return Token("REFERENCE", name)

        else:
            raise FormulaError(f"Unexpected character: {char} at position {self.pos}")


class Parser:
    """Parser implementing recursive descent for grammar adherence."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.current_token()
        self.pos += 1
        return token

    def eat(self, token_type: str, error_msg: str = None) -> Token:
        token = self.current_token()
        if token.type == token_type:
            self.advance()
            return token
        raise FormulaError(error_msg or f"Expected token type {token_type}, got {token.type} with value {token.value}")

    # Grammar Rules (Precedence: lowest to highest)
    # expr   := term {(+ | -) term}  (Left Associative)
    # term   := unary {(* | /) unary} (Left Associative)
    # unary  := (+ | -) unary | number | ref | ( expr ) (Right Associative for unary prefix)

    def parse(self) -> Node:
        # Start parsing at the lowest precedence level (expr)
        tree = self._expr()
        # Ensure we consumed everything except EOF
        if self.current_token().type != "EOF":
            raise FormulaError("Unexpected tokens found after expression completion")
        return tree

    def _expr(self) -> Node:
        # expr := term {(+ | -) term}
        node = self._term()
        while self.current_token().type in ('+', '-'):
            op_token = self.advance()
            right_node = self._term()
            # Left associativity: build tree from left
            node = BinaryOpNode(node, op_token.value, right_node)
        return node

    def _term(self) -> Node:
        # term := unary {(* | /) unary}
        node = self._unary()
        while self.current_token().type in ('*', '/'):
            op_token = self.advance()
            right_node = self._unary()
            # Left associativity
            node = BinaryOpNode(node, op_token.value, right_node)
        return node

    def _unary(self) -> Node:
        # unary := (+ | -) unary | number | ref | ( expr )
        token = self.current_token()

        if token.type in ('+', '-'):
            op_token = self.advance()
            # Unary operators are often treated as right-associative in parsing context, 
            # but since we are modeling standard mathematical unary minus/plus, 
            # we recursively call _unary to handle cases like --5.
            return UnaryOpNode(op_token.value, self._unary())
        elif token.type == '(': 
            self.advance() # Consume '(' 
            node = self._expr()
            self.eat(')', "Unbalanced parentheses: missing ')'") # Consume ')'
            return node
        elif token.type == 'NUMBER':
            self.advance()
            return NumberNode(token.value)
        elif token.type == 'REFERENCE':
            self.advance()
            return ReferenceNode(token.value)
        else:
            raise FormulaError("Expected number, reference, or unary operator/parenthesis")


# --- Public API Functions ---

def parse_formula(source: str) -> Node:
    """Parses the text after '=' into a syntax tree."""
    if not source: 
        raise FormulaError("Formula source cannot be empty after '='")

    # Tokenize the input string
    lexer = Lexer(source)
    tokens = []
    while True:
        token = lexer.next_token()
        tokens.append(token)
        if token.type == "EOF":
            break

    # Parse the token stream
    parser = Parser(tokens)
    try:
        return parser.parse()
    except FormulaError as e:
        # Re-raise any parsing errors encountered by the parser
        raise e
    except IndexError:
        # Catch issues if EOF is hit unexpectedly mid-parse
        raise FormulaError("Incomplete or malformed formula structure.")


def references(tree: Node) -> Set[str]:
    """Returns the upper-case names of the cells the formula refers to."""
    found_refs = set()

    def traverse(node: Node):
        if isinstance(node, ReferenceNode):
            found_refs.add(node.name)
        elif isinstance(node, BinaryOpNode):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        # NumberNode does nothing

    traverse(tree)
    return found_refs

