                # Check row constraints (1-999, no leading zero)
                if int(row_str) == 0 or int(row_str) > 999 or (len(row_str) > 1 and row_str.startswith('0')):
                    raise FormulaError(f"Invalid row number in reference: {node.text}")

                # Convert to uppercase as required by specification
                upper_ref = col_str.upper() + row_str
                found_refs.add(upper_ref)

                # Check if the reference is within sheet bounds (implicitly handled by row/col check, but good practice)
                # Since we only check for format, we rely on the sheet logic to catch out-of-bounds if needed.

            elif isinstance(node, BinaryOpNode):
                traverse(node.left)
                traverse(node.right)
            elif isinstance(node, UnaryOpNode):
                traverse(node.operand)
            elif isinstance(node, ParenthesisNode):
                traverse(node.expr)
