ASTNode = Union[NumberNode, RefNode, UnaryOpNode, BinaryOpNode]

# --- Core Evaluation Logic ---

def _resolve_operand_value(value: CellValue, is_pure_ref_context: bool) -> Tuple[Any, bool]:
    """Converts a cell value into a calculable type or returns error state."""
    if value is None:
        return 0, False  # Empty cell acts as 0 for calculation

    if isinstance(value, ErrorValue):
        # Pass error through
        return value, True

    if isinstance(value, str):
        # Text handling
        if is_pure_ref_context:
            # If we are in the context of a pure reference evaluation, return the text itself.
            return value, False
        else:
            # In arithmetic context, text is an error
            return ErrorValue.ERROR_GENERIC, True

    # Number (int or float)
    return value, False

def evaluate(tree: ASTNode, lookup: callable) -> CellValue:
    """Computes the formula's value given a cell value lookup function."""

    # Helper recursive evaluation function
    def _evaluate_recursive(node: ASTNode, is_pure_reference: bool) -> Tuple[CellValue, bool]:
        # Returns (result_value, is_error_or_text)

        if isinstance(node, NumberNode):
            return node.value, False

        elif isinstance(node, RefNode):
            # Rule 2: Reference gives the cell's value, except for special cases.
            raw_value = lookup(node.name)

            if raw_value is None:
                return 0, False # Empty cell -> 0

            if isinstance(raw_value, ErrorValue):
                return raw_value, True # Propagate error

            # Check if the formula is *only* a reference.
            # If is_pure_reference is True, the caller expects the string text back if it's text.
            if is_pure_reference and isinstance(raw_value, str):
                 return raw_value, False # Return text unchanged

            # Otherwise, return the value (which might be string/int/float).
            return raw_value, isinstance(raw_value, str)

        elif isinstance(node, UnaryOpNode):
            # Handle unary +/-
            operand_val, is_error = _evaluate_recursive(node.operand, is_pure_reference)

            if is_error:
                return operand_val, True # Propagate error

            if isinstance(node.op, ('+', '-')):
                if isinstance(operand_val, str):
                    return ErrorValue.ERROR_GENERIC, True

                if node.op == '+':
                    return operand_val + 0 if isinstance(operand_val, int) else operand_val + 0.0
                else: # node.op == '-' 
                    return -operand_val

            # This branch should ideally not be hit if grammar parsing is correct
            raise FormulaError(f"Unknown unary operator: {node.op}")

        elif isinstance(node, BinaryOpNode):
            # Handle binary operations (left-associative)

            # Evaluate left operand
            left_val, left_is_error = _evaluate_recursive(node.left, is_pure_reference)
            if left_is_error:
                return left_val, True # Propagate left error

            # Evaluate right operand
            right_val, right_is_error = _evaluate_recursive(node.right, is_pure_reference)
            if right_is_error:
                return right_val, True # Propagate right error

            # Check for mixed types (Text interaction)
            left_is_str = isinstance(left_val, str)
            right_is_str = isinstance(right_val, str)

            if left_is_str or right_is_str:
                # If either operand is text (and not handled by pure reference context), result is #ERROR! 
                return ErrorValue.ERROR_GENERIC, True

            # Arithmetic evaluation (operands must be numbers or 0/error value which was already filtered)

            # Rule 4: Check for ErrorValue propagation (already handled by is_error checks above, but robust check)
            if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
                return left_val if isinstance(left_val, ErrorValue) else right_val, True

            # Numeric calculation
            left_num = float(left_val) if isinstance(left_val, (int, float)) else left_val
            right_num = float(right_val) if isinstance(right_val, (int, float)) else right_val

            result: float
            if node.op == '+':
                result = left_num + right_num
            elif node.op == '-':
                result = left_num - right_num
            elif node.op == '*':
                result = left_num * right_num
            elif node.op == '/':
                if right_num == 0:
                    return ErrorValue.ERROR_GENERIC, True # Division by zero
                result = left_num / right_num
            else:
                raise FormulaError(f"Unknown binary operator: {node.op}")

            # Rule 1: Determine return type (int or float)
            if result == int(result):
                return int(result), False
            else:
                return result, False

        else:
            raise FormulaError("Unknown node type during evaluation.")

    # --- Top-Level Call Handling --- 

    # 1. Determine if the formula is *purely* a reference expression.
    # This is a simplification; a robust check would traverse the AST to see if any node is non-RefNode.
    # For this implementation, we assume a heuristic: if the top node is RefNode, it's pure ref.
    is_pure_ref = isinstance(tree, RefNode)

    if is_pure_ref:
        # Special handling for pure reference as per Rule 2
        raw_value = lookup(tree.name)
        if raw_value is None: 
            return None
        return raw_value

    # 2. Perform full calculation.
    final_value, final_is_error = _evaluate_recursive(tree, False)

    # If the final result is an ErrorValue instance, return it directly.
    if isinstance(final_value, ErrorValue):
        return final_value

    # If the final value is a string, it must have originated from a text reference that was NOT pure, 
    # which should have been converted to #ERROR! in _resolve_operand_value or the evaluation loop.
    # If it somehow remains a string here (e.g., a text literal if we allowed them, which we don't), treat as error.
    if isinstance(final_value, str) and final_value not in (ErrorValue.ERROR_GENERIC, ErrorValue.ERROR_CYCLE):
        return ErrorValue.ERROR_GENERIC

    return final_value

