import numbers
from typing import Any, Callable, Union, Set

# --- Placeholder Definitions (Assumed to exist in sheet/formula.py) ---

class ErrorValue(str):
    """Represents an error value, subclassing str to allow direct comparison.
    """
    pass

# Constants for errors
ERROR_ERROR = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# Placeholder AST Node Structure Assumption
# We assume nodes have a 'type' attribute.
# Node Types: 'number', 'ref', 'unary_op', 'binary_op', 'paren'

# --- Evaluation Function Implementation ---

def evaluate(tree: Any, lookup: Callable[[str], Any]) -> Union[int, float, str, ErrorValue]:
    """Computes the formula's value based on the AST and cell lookups.

    :param tree: The root of the expression AST.
    :param lookup: A function (name: str) -> cell_value.
    :return: The calculated value (int, float, str, or ErrorValue).
    """

    # Helper to check if a value is an error
    def is_error(val: Any) -> bool:
        return isinstance(val, ErrorValue)

    # Helper to convert value to numeric type safely for math
    def to_numeric(val: Any) -> Union[int, float, None]:
        if isinstance(val, numbers.Number):
            return val
        if val is None:
            return 0  # Rule 2: None gives 0 in arithmetic context
        if isinstance(val, (int, float)):
            return val
        # If it's a string, it's either text or a recognized ErrorValue
        if isinstance(val, str) and not is_error(val):
            # If it's text, we treat it as non-numeric for math, letting error handling catch it.
            return None 
        return None

    # --- Core Recursive Evaluator --- 
    def _eval_recursive(node: Any) -> Union[int, float, str, ErrorValue]:
        if not hasattr(node, 'type'):
            raise TypeError("AST node must have a 'type' attribute.")

        node_type = node.type

        # 1. Base Case: Number Literal
        if node_type == 'number':
            return node.value

        # 2. Base Case: Reference
        if node_type == 'ref':
            name = node.name
            cell_value = lookup(name)

            # Rule 2 special case: Formula consisting only of a reference
            # This function doesn't know if it's the sole component, so we apply the general rules.
            # If cell_value is None, we must determine if we return 0 (math) or text (sole ref).
            # Since this recursive helper cannot know the context, we follow the primary math rule: None -> 0.
            # The specific 'return text unchanged' rule requires external context, which we approximate by handling None as 0 for math operations.

            if cell_value is None:
                # If None, return 0 for calculations, but this is tricky for the sole reference case.
                # Returning 0 here ensures math operations involving this reference work correctly.
                return 0 
            if is_error(cell_value):
                return cell_value
            if isinstance(cell_value, str):
                return cell_value # Text remains text
            return cell_value # Numeric

        # 3. Recursive Case: Unary Operation
        if node_type == 'unary_op':
            operand_val = _eval_recursive(node.operand)
            op = node.op

            # Error propagation (Unary op doesn't introduce new errors, just propagates)
            if is_error(operand_val):
                return operand_val

            if isinstance(operand_val, str) and not is_error(operand_val):
                # Text operand under unary op leads to #ERROR!
                return ERROR_ERROR

            try:
                num_operand = to_numeric(operand_val)
                if num_operand is None: return ERROR_ERROR # Should have been caught by text check

                if op == '+':
                    return num_operand
                elif op == '-':
                    return -num_operand
                # Unary multiplication/division is not in grammar, so this handles only +/-
                raise ValueError("Invalid unary operator.")
            except Exception: # Catch if operand wasn't numeric after all
                 return ERROR_ERROR

        # 4. Recursive Case: Binary Operation
        if node_type == 'binary_op':
            left_val = _eval_recursive(node.left)
            right_val = _eval_recursive(node.right)
            op = node.op

            # Rule 3: Error Propagation
            if is_error(left_val):
                return left_val # Left one wins
            if is_error(right_val):
                return right_val

            # Rule 3: Text Propagation
            if isinstance(left_val, str) and not is_error(left_val):
                return ERROR_ERROR
            if isinstance(right_val, str) and not is_error(right_val):
                return ERROR_ERROR

            # Numeric Evaluation (Rule 4)
            L_num = to_numeric(left_val)
            R_num = to_numeric(right_val)

            if L_num is None or R_num is None:
                 # This should only happen if an operand evaluated to non-error text that wasn't caught above,
                 # or if the structure implies a non-numeric result that isn't text (e.g., complex object).
                 # Given the grammar, this implies text that wasn't caught or an unexpected structure.
                 return ERROR_ERROR

            try:
                if op == '+':
                    return L_num + R_num if isinstance(L_num, int) and isinstance(R_num, int) else float(L_num) + float(R_num)
                elif op == '-':
                    return L_num - R_num if isinstance(L_num, int) and isinstance(R_num, int) else float(L_num) - float(R_num)
                elif op == '*':
                    return L_num * R_num if isinstance(L_num, int) and isinstance(R_num, int) else float(L_num) * float(R_num)
                elif op == '/':
                    if R_num == 0:
                        return ERROR_ERROR # Division by zero
                    return float(L_num) / float(R_num)
                raise ValueError("Unsupported binary operator.")
            except Exception:
                # Catches type mismatches that slip through or other arithmetic failures
                return ERROR_ERROR

        # 5. Parenthesized Expression
        if node_type == 'paren':
            return _eval_recursive(node.expr)

        raise NotImplementedError(f"Evaluation for node type '{node_type}' is not implemented.")

    # --- Execution --- 
    # Handling the sole reference case (Rule 2) requires knowing if the root is a ref. 
    # If it is, we check the raw value.
    if tree.type == 'ref':
        name = tree.name
        raw_value = lookup(name)

        if raw_value is None:
            # Empty cell
            return 0 # Defaulting to 0 if evaluation is forced
        if isinstance(raw_value, str) and not is_error(raw_value):
            return raw_value # Text unchanged
        # If it's numeric or error, return it directly
        return raw_value

    return _eval_recursive(tree)

