import re

class FormulaError(ValueError):
    """Raised for errors during formula parsing or validation."""
    pass

class ErrorValue(str):
    """Base class for error values, inheriting from str for comparison."""
    pass

# Concrete Error Values
ERROR_NOT_CALCULATED = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- Tokenization ---

TOKEN_SPECIFICATION = [
    ('NUMBER', r'\d+(\.\d*)?'),
    ('REF', r'[a-zA-Z]{1,2}[1-9]\d*'),  # Simplified check for structure, validation happens later
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('PLUS', r'\+'),
    ('MINUS', r'\-'),
    ('MUL', r'\*'),
    ('DIV', r'\/'),
    ('SKIP', r'[ \t]+'),
    ('MISMATCH', r'.'),
]
TOKEN_REGEX = '|'.join('(?P<%s>%s)' % pair for pair in TOKEN_SPECIFICATION)

class Token:
    def __init__(self, type, value, line, col):
        self.type = type
        self.value = value
        self.line = line
        self.col = col

class Lexer:
    def __init__(self, text):
        self.text = text
        self.tokens = self._tokenize(text)

    def _tokenize(self, text):
        tokens = []
        line_num = 1
        line_start = 0
        for mo in re.finditer(TOKEN_REGEX, text):
            kind = mo.lastgroup
            value = mo.group()
            start = mo.start()
            end = mo.end()

            if kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise FormulaError(f"Unexpected character: {value}")

            # Simple way to track line/col for error reporting if needed, though not strictly required by prompt
            line_num += value.count('\n')
            col = start - text.rfind('\n', 0, start) - 1

            tokens.append(Token(kind, value, line_num, col))

        return tokens

# --- AST Nodes ---

class Node:
    """Base class for AST nodes."""
    pass

class Number(Node):
    def __init__(self, token):
        self.token = token
        self.value = float(token.value) if '.' in token.value else int(token.value)

class Ref(Node):
    def __init__(self, token):
        self.token = token
        self.name = token.value.upper() # Store as upper case

class BinaryOp(Node):
    def __init__(self, left, op_token, right):
        self.left = left
        self.op_token = op_token
        self.right = right

class UnaryOp(Node):
    def __init__(self, operand, op_token):
        self.operand = operand
        self.op_token = op_token

class Grouping(Node):
    def __init__(self, expr):
        self.expr = expr

# --- Parser ---

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self):
        self.pos += 1

    def eat(self, expected_type=None, expected_value=None):
        token = self.current_token()
        if token is None:
            raise FormulaError("Unexpected end of expression.")

        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected token type {expected_type}, got {token.type} ('{token.value}')")
        if expected_value and token.value != expected_value:
             raise FormulaError(f"Expected token value '{expected_value}', got '{token.value}'")

        self.advance()
        return token

    # Grammar implementation (Precedence: Unary > */ > +-)

    def parse_formula(self):
        # Start parsing at the lowest precedence level: expression
        node = self._parse_expression()

        # After parsing the expression, ensure all tokens are consumed
        if self.current_token() is not None:
            raise FormulaError(f"Unparsed trailing input starting with: {self.current_token().value}")

        return node

    def _parse_expression(self):
        # Handles + and - (Left-associative)
        node = self._parse_term()

        while self.current_token() and self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.eat()
            right = self._parse_term()
            # Left associativity: new operation wraps the previous result
            node = BinaryOp(node, op_token, right)

        return node

    def _parse_term(self):
        # Handles * and / (Left-associative)
        node = self._parse_unary()

        while self.current_token() and self.current_token().type in ('MUL', 'DIV'):
            op_token = self.eat()
            right = self._parse_unary()
            # Left associativity
            node = BinaryOp(node, op_token, right)

        return node

    def _parse_unary(self):
        # Handles unary + and - (Highest binding)
        token = self.current_token()
        if token and token.type in ('PLUS', 'MINUS'):
            op_token = self.eat()
            # Unary operator applies to the next parsed element
            operand = self._parse_unary() # Keep calling unary to handle --5 correctly
            return UnaryOp(operand, op_token)

        # If not unary, proceed to factor
        return self._parse_factor()

    def _parse_factor(self):
        # Handles numbers, references, and grouped expressions
        token = self.current_token()
        if not token:
             raise FormulaError("Unexpected end of input while expecting factor.")

        if token.type == 'NUMBER':
            self.eat('NUMBER')
            return Number(token)

        elif token.type == 'REF':
            # Validation check: Sheet constraints
            ref_value = token.value
            # 1. Max 2 letters (A-Z), 2. Row 1-999, 3. No leading zeros on row
            if not (1 <= len(ref_value) <= 2 and ref_value[0].isalpha() and ref_value[1:].isdigit()):
                 raise FormulaError(f"Invalid cell reference format: {ref_value}")

            # Check for row constraints: Row > 0 and Row <= 999
            try:
                row_str = ref_value[1:]
                row_num = int(row_str)

                # Check for leading zero if more than one digit
                if len(row_str) > 1 and row_str[0] == '0':
                     raise FormulaError(f"Invalid cell reference: Leading zero in row {ref_value}")

                if not (1 <= row_num <= 999):
                    raise FormulaError(f"Cell reference out of bounds (1-999): {ref_value}")

            except ValueError:
                # This handles cases where row_str is empty or not digits, though token type suggests digits follow letters.
                raise FormulaError(f"Invalid cell reference: {ref_value}")

            self.eat('REF')
            return Ref(token)

        elif token.type == 'LPAREN':
            self.eat('LPAREN')
            node = self._parse_expression()
            self.eat('RPAREN')
            return Grouping(node)

        else:
            raise FormulaError(f"Unexpected token type in factor: {token.type} ('{token.value}')")

# --- Public Interface ---

def parse_formula(source: str) -> Node:
    """Parses the text after '=' into a syntax tree."""
    if not source.strip():
        raise FormulaError("Formula input is empty.")

    # Tokenize
    lexer = Lexer(source)

    # Parse
    parser = Parser(lexer.tokens)
    return parser.parse_formula()

