import re

class Version:
    """Represents a package version in MAJOR.MINOR.PATCH format."""
    def __init__(self, text: str):
        self.text = text
        self._parts = self._parse(text)
        self.major = self._parts[0]
        self.minor = self._parts[1]
        self.patch = self._parts[2]

    def _parse(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version '{text}' must have exactly three parts separated by dots.")

        nums = []
        for part in parts:
            # Check for non-negative integer and no leading zeros (unless the part is '0')
            if not part.isdigit():
                raise ValueError(f"Version part '{part}' is not a valid integer.")
            if len(part) > 1 and part.startswith('0'):
                raise ValueError(f"Version part '{part}' cannot have leading zeros unless it is '0'.")
            nums.append(int(part))
        return nums

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other):
        return self > other or self == other

