    def from_dict(cls, data: dict) -> 'PackageIndex':
        """Builds a PackageIndex from a nested dictionary structure.

        :param data: Dictionary structure: {name: {version: {dep: spec, ...}, ...}, ...}
        :return: A fully populated PackageIndex instance.
        :raises ValueError: If any version or spec is invalid during loading.
        """
        index = cls()
        for name, versions_data in data.items():
            for version, details in versions_data.items():
                # Details here are assumed to be {dep: spec, ...}
                if not isinstance(version, str):
                     raise ValueError(f"Version key for {name} must be a string.")

                # Check if version is valid before adding
                try:
                    Version(version)
                except ValueError as e:
                    raise ValueError(f"Invalid version '{version}' for package {name}: {e}")

                requires = {}
                for dep_name, spec in details.items():
                    if not isinstance(spec, str):
                        raise ValueError(f"Requirement specification for {dep_name} in {name}@{version} must be a string.")
                    try:
                        Range(spec)
                        requires[dep_name] = spec # Store string spec for re-parsing during add if needed, though add handles it
                    except ValueError as e:
                        raise ValueError(f"Invalid range specification '{spec}' for {dep_name} in {name}@{version}: {e}")

                # Add using the internal logic (or simplify by using the existing add method if we adapt it)
                # For simplicity here, we'll rely on the fact that 'add' expects string specs
                # We need to pass the actual spec strings, not Range objects.
                index.add(name, version, requires)

        return index
