class Range:
    """Represents a version range constraint."""
    # Regex to capture operators and version strings, ignoring surrounding whitespace
    # Operators: ==, !=, >=, <=, >, <, ^, ~
    # Special case: * (wildcard)
    CONSTRAINT_REGEX = re.compile(r"(?P<op>==|!=|>=|<=|>|<|\^|~)?\s*(?P<version>[0-9]+\.[0-9]+\.[0-9]+)?")

    def __init__(self, spec: str):
        self._original_spec = spec
        self._constraints = []
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        # Split by comma, then clean up whitespace around constraints
        constraints_str = [c.strip() for c in spec.split(',')]

        if not spec.strip():
            self._constraints.append({"op": "*", "version": None})
            return

        for constraint_str in constraints_str:
            if not constraint_str: # Handles trailing commas like '1.0.0,'
                continue

            if constraint_str == "*":
                self._constraints.append({"op": "*", "version": None})
                continue

            # Check for specific operators and versions
            match = re.match(r"^(?P<op>[!=><^~]=?|==)?\s*(?P<version>[0-9]+\.[0-9]+\.[0-9]+)$", constraint_str.strip())

            if match:
                op = match.group("op") or "==" # Default to == if no operator specified before version (e.g., '1.2.3' implies '==1.2.3')
                version_str = match.group("version")

                if not version_str:
                    raise ValueError(f"Invalid constraint format: '{constraint_str}'. Missing version.")

                try:
                    version = Version(version_str)
                    self._constraints.append({"op": op, "version": version})
                except ValueError as e:
                    # Catch errors from Version constructor (bad format)
                    raise ValueError(f"Invalid version in constraint '{constraint_str}': {e}")
            else:
                # Handle constraints that might just be a version string if no operator was matched above, 
                # or more complex/unknown operators
                # Re-evaluate the case where just '1.2.3' was passed without an operator, which we handle as '==' above.
                # If we reach here, it's likely an unsupported operator or a badly formed string.

                # Final check for patterns not caught, especially complex ones if the regex above missed them
                if constraint_str.strip() in ('*',): 
                     # This should have been caught earlier, but as a failsafe
                     self._constraints.append({"op": "*", "version": None})
                     continue

                # If it fails the specific regex, raise an error for unknown formats
                raise ValueError(f"Unrecognized or invalid constraint '{constraint_str}'.")

        # Post-processing and normalization for complex operators (^, ~)
        self._normalize_ranges()

    def _normalize_ranges(self):
        normalized_constraints = []
        for constraint in self._constraints:
            op = constraint['op']
            version = constraint['version']

            if op == "*":
                normalized_constraints.append(constraint)
                continue

            if op == "^":
                # ^MAJOR.MINOR.PATCH: >=V, <NEXT_MAJOR
                v = version
                if not v: raise ValueError("Missing version for caret (^).")

                next_major = Version(f"{v.major + 1}.0.0")
                normalized_constraints.append({"op": ">=", "version": v})
                normalized_constraints.append({"op": "<", "version": next_major})

            elif op == "~":
                # ~MAJOR.MINOR.PATCH: >=V, <V.MINOR+1.0 (if MINOR>0) or <V.MAJOR+1.0 (if MINOR=0 and PATCH=0)
                v = version
                if not v: raise ValueError("Missing version for tilde (~).")

                if v.minor > 0:
                    # e.g., ^1.2.3 -> >=1.2.3, <1.3.0
                    next_minor = Version(f"{v.major}.{v.minor + 1}.0")
                elif v.major > 0: # v.minor == 0, v.patch > 0
                    # e.g., ^1.0.3 -> >=1.0.3, <1.1.0
                    next_minor = Version(f"{v.major}.{v.minor + 1}.0")
                else: # v.major == 0, v.minor == 0, v.patch == 0
                    # e.g., ^0.0.0 -> >=0.0.0, <0.0.1
                    next_minor = Version(f"{v.major}.{v.minor}.{v.patch + 1}")

                normalized_constraints.append({"op": ">=", "version": v})
                normalized_constraints.append({"op": "<", "version": next_minor})

            # Other standard operators (==, !=, >=, <=, >, <) are kept as is
            else:
                normalized_constraints.append(constraint)

        self._constraints = normalized_constraints

    def contains(self, v: Version) -> bool:
        """Tests if a Version satisfies the range constraint."""
        for constraint in self._constraints:
            op = constraint['op']
            v_ref = constraint['version']

            if op == "*":
                continue # Wildcard always matches

            if not v_ref:
                # Should not happen if parsing is correct, but defensively skip
                continue 

            if op == "==":
                if v != v_ref:
                    return False
            elif op == "!=":
                if v == v_ref:
                    return False
            elif op == ">=":
                if v < v_ref:
                    return False
            elif op == "<":
                if v >= v_ref:
                    return False
            elif op == ">":
                if v <= v_ref:
                    return False
            elif op == "<":
                if v >= v_ref:
                    return False
            elif op == "": # This line is redundant/erroneous in thought process, handled above
                pass
            # Note: The initial regex parsing might produce redundant constraints if '^' or '~' are present,
            # but the normalization handles this by expanding them into explicit >= and < constraints.
            # The current structure handles standard comparison operators correctly.

        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self) -> str:
        # Reconstruct the spec string from normalized constraints, ensuring no whitespace
        parts = []
        # Use a set to avoid duplicating the exact same constraint in the string representation,
        # though the parsing should handle most duplication.
        seen_specs = set()

        for constraint in self._constraints:
            op = constraint['op']
            v_ref = constraint['version']

            if op == "*":
                parts.append("*")
                continue

            if v_ref:
                spec = f"{op}{v_ref}"
                if spec not in seen_specs:
                    parts.append(spec)
                    seen_specs.add(spec)

        return " ".join(parts).replace(" ", "") # Joining with space then removing spaces achieves the required removal of all whitespace


