from .versions import Version, Range
from collections import defaultdict

class PackageIndex:
    """
    Stores package releases and their dependencies.
    """
    def __init__(self):
        # {name: {version_str: {'requires': {dep_name: Range, ...}}}}
        self._releases = defaultdict(dict)

    def add(self, name: str, version: str, requires: dict = None) -> None:
        """Adds a specific package release.

        :param name: Package name.
        :param version: Version string (e.g., '1.2.3').
        :param requires: Dictionary mapping dependency names to Range specifications.
        """
        if version in self._releases[name]:
            raise ValueError(f"Version {version} already exists for package {name}.")

        if requires is None:
            requires = {}

        # Validate version string using Version class
        try:
            Version(version)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version}': {e}")

        # Validate range specs
        for dep_name, spec in requires.items():
            try:
                Range(spec)
            except ValueError as e:
                raise ValueError(f"Invalid range specification for {dep_name} ({spec}): {e}")

        self._releases[name][version] = {"requires": requires}

    def versions(self, name: str) -> list[Version]:
        """
        Returns all known versions of a package, newest first.

        :param name: Package name.
        :return: List of Version objects.
        """
        versions = []
        if name in self._releases:
            # Extract versions and sort them numerically, newest first
            version_strings = list(self._releases[name].keys())
            versions = [Version(v) for v in version_strings]
            # Sorting relies on Version comparison: v1 > v2 means v1 is newer
            versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version: str) -> dict[str, Range]:
        """
        Returns the dependency ranges for a specific version of a package.

        :param name: Package name.
        :param version: Specific version string.
        :return: Dictionary mapping dependency names to Range objects.
        :raises KeyError: If the package/version combination is not found.
        """
        if name not in self._releases or version not in self._releases[name]:
            raise KeyError(f"Package {name} version {version} not found in index.")

        release_data = self._releases[name][version]
        # Convert string specifications to Range objects
        range_specs = {}
        for dep_name, spec in release_data["requires"].items():
            try:
                range_specs[dep_name] = Range(spec)
            except ValueError as e:
                # This should ideally not happen if add() validated correctly
                raise RuntimeError(f"Internal error: Failed to parse stored range for {dep_name} {spec}: {e}")

        return range_specs

    @classmethod
    def from_dict(cls, data: dict) -> 'PackageIndex':
        """Builds a PackageIndex from a nested dictionary structure.

        :param data: Dictionary structure: {name: {version: {dep: spec, ...}, ...}, ...}
        :return: A fully populated PackageIndex instance.
        :raises ValueError: If any version or spec is invalid during loading.
        """
        index = cls()
        for name, versions_data in data.items():
            for version, details in versions_data.items():
                # Details here are assumed to be {dep: spec, ...}
                if not isinstance(version, str):
                     raise ValueError(f"Version key for {name} must be a string.")

                # Check if version is valid before adding
                try:
                    Version(version)
                except ValueError as e:
                    raise ValueError(f"Invalid version '{version}' for package {name}: {e}")

                requires = {}
                for dep_name, spec in details.items():
