import re
from typing import Tuple

class Version: 
    """Represents a semantic version MAJOR.MINOR.PATCH."""

    def __init__(self, text: str):
        """Parses the version string and validates the format."""
        match = re.fullmatch(r"([0-9]+)\.([0-9]+)\.([0-9]+)", text)
        if not match:
            raise ValueError(f"Version '{text}' must be in MAJOR.MINOR.PATCH format.")

        self.major = int(match.group(1))
        self.minor = int(match.group(2))
        self.patch = int(match.group(3))
        self.tuple_form = (self.major, self.minor, self.patch)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.tuple_form == other.tuple_form

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.tuple_form < other.tuple_form

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.tuple_form > other.tuple_form

    def __ge__(self, other):
        return self > other or self == other

    def __hash__(self):
        return hash(self.tuple_form)

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

