import re
from typing import List, Tuple

# Assuming Version class is available from above context

class Range:
    """Represents a version range specification."""

    OPERATORS = {
        "==": lambda v, target: v == target,
        "!=": lambda v, target: v != target,
        ">=": lambda v, target: v >= target,
        "<=": lambda v, target: v <= target,
        ">": lambda v, target: v > target,
        "<": lambda v, target: v < target,
    }

    def __init__(self, spec: str):
        # 1. Handle whitespace and empty spec
        spec = spec.strip()
        if not spec:
            raise ValueError("Range spec cannot be empty.")

        self.constraints: List[Tuple[str, Version]] = []
        self.raw_spec = spec

        # Regex to find constraints: (operator/prefix) + version OR just '*' 
        # It captures: (operator/prefix) (optional space) (version) OR just '*' 
        constraint_pattern = r'([=!<>~^]*)(.*?)(,|$)'

        parts = re.split(r'(?<=[,])\s*', spec)

        for part in parts:
            part = part.strip()
            if not part: continue

            # Check for the '*' wildcard
            if part == "*":
                self.constraints.append(('*', Version("0.0.0"))) # Dummy version for * constraint
                continue

            # Try to parse as standard operator constraint
            match = re.match(r'([=!<>~^]+)\s*([0-9.]+)', part)
            if match:
                op_str = match.group(1)
                version_str = match.group(2)
                try:
                    version = Version(version_str)
                except ValueError:
                    raise ValueError(f"Bad version in range spec: {version_str}")

                # Handle prefix operators (^, ~)
                if op_str.startswith('^'):
                    op_str = '^'
                    version = self._handle_caret(version, op_str)
                    self.constraints.append((op_str, version))
                    continue
                elif op_str.startswith('~'):
                    op_str = '~'
                    version = self._handle_tilde(version, op_str)
                    self.constraints.append((op_str, version))
                    continue

                # Handle standard operators
                if op_str in self.OPERATORS:
                    self.constraints.append((op_str, version))
                    continue

                # Handle exact match if no operator was explicitly found but it's a version
                if re.fullmatch(r'[0-9.]+', part):
                     # This implies a bare version, treat as ==
                    self.constraints.append(('==', version))
                    continue

                # If it reaches here, the operator is unknown or the format is invalid
                raise ValueError(f"Unknown operator or bad format in constraint: {part}")

            # If no clear operator match, check if it's a bare version (treat as ==)
            elif re.fullmatch(r'[0-9.]+', part):
                try:
                    version = Version(part)
                    self.constraints.append(('==', version))
                except ValueError:
                    raise ValueError(f"Bad version in range spec: {part}")
            else:
                raise ValueError(f"Malformed range constraint: {part}")

        # Final validation: ensure no empty constraints were left dangling
        if not self.constraints:
             raise ValueError("Range spec resulted in no valid constraints.")

    def _handle_caret(self, v: Version, op: str) -> Version:
        """Handles ^ (caret) range logic: >=v, <next_major_or_minor_bump."""
        major, minor, patch = v.tuple_form

        if major == 0 and minor == 0 and patch == 0:
            # ^0.0.0 is >=0.0.0, <0.0.1
            return Version("0.0.1") # We only need the upper bound for the check
        elif major == 0:
            # ^0.2.3 is >=0.2.3, <0.3.0
            next_minor = minor + 1
            return Version(f"0.{next_minor}.0")
        else:
            # ^1.2.3 is >=1.2.3, <2.0.0
            next_major = major + 1
            return Version(f"{next_major}.0.0")

    def _handle_tilde(self, v: Version, op: str) -> Version:
        """Handles ~ (tilde) range logic: >=v, <minor_bump."""
        major, minor, patch = v.tuple_form

        if patch == 0:
            # ~1.2.0 is >=1.2.0, <1.3.0
            next_minor = minor + 1
            return Version(f"{major}.{next_minor}.0")
        else:
            # ~1.2.3 is >=1.2.3, <1.2.4
            next_patch = patch + 1
            return Version(f"{major}.{minor}.{next_patch}")

    def contains(self, v: Version) -> bool:
        """Checks if the given Version satisfies all constraints in the range."""
        for op, constraint_v in self.constraints:
            if op == '*':
                continue # '*' always passes

            # For caret/tilde ranges, the stored constraint_v is the *exclusive* upper bound
            # If the operator was ^ or ~, the check is against the upper bound generated in __init__
            if op in ('^', '~'):
                # Check if v is less than the calculated upper bound
                if v >= constraint_v:
                    return False

            # For standard operators (==, >=, etc.)
            elif op in self.OPERATORS:
                if not self.OPERATORS[op](v, constraint_v):
                    return False

        return True

    def __str__(self) -> str:
        # Return spec with all whitespace removed
        return self.raw_spec.replace(" ", "")

