import re
from typing import Dict, List, Optional, Tuple
from .versions import Version, Range

class PackageIndex:
    """A database storing all known package releases and their dependencies."""

    def __init__(self):
        # Structure: {package_name: {version_string: {dependency_name: Range}}}
        # Storing Range objects directly for consistency
        self._releases: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a release of a package to the index."""
        if requires is None:
            requires = {}

        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version_str}': {e}")

        if name not in self._releases:
            self._releases[name] = {}

        if version_str in self._releases[name]:
            raise ValueError(f"Version {version_str} already exists for package {name}")

        release_deps: Dict[str, Range] = {}
        for dep_name, spec in requires.items():
            try:
                release_deps[dep_name] = Range(spec)
            except ValueError as e:
                raise ValueError(f"Invalid requirement spec for {name}@{version_str} on {dep_name}: {e}")

        self._releases[name][version_str] = release_deps

    def versions(self, name: str) -> List[Version]:
        """Returns a list of known Version objects for a package, newest first."""
        if name not in self._releases:
            return []

        versions = []
        for version_str in self._releases[name].keys():
            versions.append(Version(version_str))

        # Sort versions numerically, newest first
        versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version_str: str) -> Dict[str, Range]:
        """Returns a dict mapping each dependency name to its Range for a given version."""
        if name not in self._releases or version_str not in self._releases[name]:
            raise KeyError(f"No version {version_str} found for package {name}")
        return self._releases[name][version_str]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a dictionary structure."""
        index = cls()
        for name, version_data in data.items():
            for version_str, requirements in version_data.items():
                requires_str: Optional[Dict[str, str]] = requirements
                index.add(name, version_str, requires_str)
        return index
