import re
from typing import Dict, List, Optional, Tuple
from .versions import Version, Range

class PackageIndex:
    """A database storing all known package releases and their dependencies."""

    def __init__(self):
        # Structure: {package_name: {version_string: {dependency_name: Range}}}
        # Storing Range objects directly for consistency
        self._releases: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a release of a package to the index."""
        if requires is None:
            requires = {}

        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version_str}': {e}")

        if name not in self._releases:
            self._releases[name] = {}

        if version_str in self._releases[name]:
            raise ValueError(f"Version {version_str} already exists for package {name}")

        release_deps: Dict[str, Range] = {}
        for dep_name, spec in requires.items():
            try:
                release_deps[dep_name] = Range(spec)
            except ValueError as e:
                raise ValueError(f"Invalid requirement spec for {name}@{version_str} on {dep_name}: {e}")

        self._releases[name][version_str] = release_deps

    def versions(self, name: str) -> List[Version]:
        """Returns a list of known Version objects for a package, newest first."""
        if name not in self._releases:
            return []

        versions = []
        for version_str in self._releases[name].keys():
            versions.append(Version(version_str))

        # Sort versions numerically, newest first
        versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version_str: str) -> Dict[str, Range]:
        """Returns a dict mapping each dependency name to its Range for a given version."""
        if name not in self._releases or version_str not in self._releases[name]:
            raise KeyError(f"No version {version_str} found for package {name}")
        return self._releases[name][version_str]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a dictionary structure."""
        index = cls()
        for name, version_data in data.items():
            for version_str, requirements in version_data.items():
                requires_str: Optional[Dict[str, str]] = requirements
                index.add(name, version_str, requires_str)
        return index

from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional, Iterable, Tuple, List
import json
import re
from calendar import month_abbr

class ParseError(ValueError):
    """Raised when a line fails parsing according to the rules."""
    pass

@dataclass(frozen=True)
class Record:
    """Normalised log record.
    Time must be timezone-aware and in UTC.
    """
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: Optional[float] = None

# --- Normalization Logic ---

def normalize(time: datetime, client: str, method: str, path: str, status: int, size: Optional[str | int], latency_ms: Optional[str | float]) -> Record:
    """Applies validation and transformation rules to raw parsed fields."""

    # 1. Time check (Already handled by parsers to be aware and UTC, but double check structure)
    if not isinstance(time, datetime) or time.tzinfo is None or time.utcoffset() is None:
        raise ParseError("Time must be timezone-aware and in UTC.")
    # Ensure it is UTC
    time = time.astimezone(timezone.utc)

    # 2. Client check
    if not isinstance(client, str) or not client:
        raise ParseError("Client must be a non-empty string.")

    # 3. Method check
    if not isinstance(method, str) or not method.isalpha() or not method.isupper():
        raise ParseError("Method must be a non-empty string of ASCII letters (uppercase).")
    method = method.upper()

    # 4. Path check
    if not isinstance(path, str) or not path.startswith('/'):
        raise ParseError("Path must start with '/'.")

    # Remove query/fragment and collapse slashes
    path_stripped = path.split('?')[0].split('#')[0]
    path = re.sub(r'/+', '/', path_stripped)

    # 5. Status check
    if not isinstance(status, int) or not (100 <= status <= 599):
        raise ParseError(f"Status code {status} is invalid. Must be between 100 and 599.")

    # 6. Size check
    size = 0
    if size is None or size == "-":
        size = 0
    else:
        try:
            size = int(size)
            if size < 0:
                raise ParseError("Size must be non-negative.")
        except (ValueError, TypeError):
            raise ParseError("Size must be an integer or '-'/None.")

    # 7. Latency check
    latency_ms = None
    if latency_ms is not None and latency_ms != "-":
        try:
            latency_ms = float(latency_ms)
            if latency_ms < 0:
                raise ParseError("Latency must be non-negative.")
        except (ValueError, TypeError):
            raise ParseError("Latency must be a non-negative number or None/'-'.")

    return Record(
        time=time,
        client=client,
        method=method,
        path=path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

# --- CLF Parser ---

# Regex breakdown based on example: 127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /apache_pb.gif?x=1 HTTP/1.0" 200 2326 (optional latency)
# Captures: (client_ip), (ident), (user), (time_str), (request_line), (status), (size), (optional_latency)
CLF_RE = re.compile(r'( ?
)?( ?
)?( ?
)?( ?
)?([^ ]+) - [^ ]+ \[([^\]]+)\] "([A-Z]+) (.*?) HTTP/[0-9\]\.\]" ( ?
)?([0-9-]+)?(?: ([-]?\d+))?(?:?
)?')

# Custom time parser for CLF: DD/Mon/YYYY:HH:MM:SS ±HHMM
# Maps English month abbreviations to numbers for datetime parsing
MONTH_MAP = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
}

def clf_time_parser(time_str: str) -> datetime:
    """Parses CLF time string and converts it to timezone-aware UTC datetime."""
    # Example format: 10/Oct/2000:13:55:36 -0700
    match = re.match(r'( ?
)?( ?
)?( ?
)?([0-9]{2})/([A-Za-z]{3})/([0-9]{4}):([0-9]{2}):([0-9]{2}):([0-9]{2}) ([+-][0-9]{4})', time_str)

    if not match:
        raise ParseError(f"Time string format invalid: {time_str}")

    day, month_abbr, year, hour, minute, second, tz_offset_str = match.groups()[3:]

    month = MONTH_MAP[month_abbr]

    # Parse offset: [+|-]HHMM
    sign = 1 if tz_offset_str[0] == '+' else -1
    offset_hours = int(tz_offset_str[1:3])
    offset_minutes = int(tz_offset_str[3:5])

    total_offset_seconds = (offset_hours * 3600 + offset_minutes * 60) * sign

    # Create naive datetime
    try:
        dt_naive = datetime(int(year), month, int(day), int(hour), int(minute), int(second))
    except ValueError as e:
        raise ParseError(f"Date components invalid: {e}")

    # Make aware using the parsed offset
    # datetime.fromtimestamp/timezone is complex here, so we create an offset object manually for precision.
    from datetime import timedelta
    offset_delta = timedelta(seconds=total_offset_seconds)
    dt_aware = dt_naive.replace(tzinfo=timezone(offset_delta))

    # Convert to UTC
    return dt_aware.astimezone(timezone.utc)


def parse_clf(line: str) -> Record:
    """Parses a Common Log Format line into a Record object."""
    try:
        # Use a simpler regex for extraction matching the structure closely
        # Group 1: Client IP
        # Group 2: Time string
        # Group 3: Method
        # Group 4: Path
        # Group 5: Status
        # Group 6: Size (or '-')
        # Group 7: Latency (optional)
        match = re.match(r'( ?
)?([^ ]+) - [^ ]+ \[([^\]]+)\] "([A-Z]+) ([^ ]+) .*?" ( ?
)?([0-9-]+)?(?: ([-]?\d+))?(?:?
)?', line.strip())

        if not match:
            raise ParseError("CLF line structure does not match expected format.")

        # Groups: IP, TimeStr, Method, Path, Status, Size, Latency
        groups = match.groups()

        client = groups[1].strip() # IP
        time_str = groups[2].strip()
        method = groups[3].strip()
        path = groups[4].strip()
        status_str = groups[5].strip() or "0"
        size_str = groups[6].strip() if groups[6] else "-"
        latency_str = groups[7].strip() if groups[7] else None

        # Convert types
        status = int(status_str)

        # Parse time
        time = clf_time_parser(time_str)

        # Normalize
        return normalize(
            time=time,
            client=client,
            method=method,
            path=path,
            status=status,
            size=size_str,
            latency_ms=latency_str
        )

    except ParseError as e:
        raise e
    except Exception as e:
        raise ParseError(f"Unexpected error during CLF parsing: {e}")

# --- JSONL Parser ---

def parse_jsonl(line: str) -> Record:
    """Parses a JSON line into a Record object, applying normalization rules."""
    try:
        data = json.loads(line)

        # Check for required keys and basic types
        required_keys = ['ts', 'client', 'method', 'path', 'status']
        for key in required_keys:
            if key not in data:
                raise ParseError(f"Missing required JSON field: {key}")

        ts_str = data['ts']
        client = data['client']
        method = data['method']
        path = data['path']
        status = data['status']

        # Parse time (ISO 8601, handles Z or offset)
        try:
            if isinstance(ts_str, str):
                if ts_str.endswith('Z'):
                    # Handle 'Z' by replacing with +00:00 for standard parsing
                    dt = datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
                else:
                    dt = datetime.fromisoformat(ts_str)

                if dt.tzinfo is None or dt.tzinfo.utcoffset(dt) is None:
                    raise ParseError("Time field must be timezone-aware.")
                dt = dt.astimezone(timezone.utc)
            else:
                 raise ParseError("Timestamp must be a string.")
        except ValueError as e:
            raise ParseError(f"Invalid timestamp format in JSON: {ts_str}. Error: {e}")

        # Parse optional fields
        size = data.get('bytes')
        latency_ms = data.get('latency_ms')

        # Apply normalization rules
        return normalize(
            time=dt, 
            client=str(client),
            method=str(method),
            path=str(path),
            status=int(status),
            size=size,
            latency_ms=latency_ms
        )

    except json.JSONDecodeError:
        raise ParseError("Line is not valid JSON.")
    except TypeError: # Handles if data is not a dict or keys are wrong type initially
        raise ParseError("JSON record is not a valid object.")

# --- Dispatcher and Reader ---

def parse_line(line: str, fmt: str = 'auto') -> Record:
    """Dispatches to the correct parser based on the format hint or line content."""
    line = line.strip()
    if not line:
        raise ParseError("Cannot parse empty line.")

    if fmt == 'clf':
        return parse_clf(line)

    if fmt == 'jsonl':
        return parse_jsonl(line)

    if fmt == 'auto':
        # JSON parser when line starts with '{', otherwise CLF parser
        if line.startswith('{'):
            return parse_jsonl(line)
        else:
            return parse_clf(line)

    raise ValueError(f"Unsupported format specified: {fmt}. Must be 'clf', 'jsonl', or 'auto'.")

def read_records(lines: Iterable[str], fmt: str = 'auto') -> Tuple[List[Record], List[int]]:
    """Reads an iterable of lines, parses them, and tracks bad lines."""
    records: List[Record] = []
    bad_lines: List[int] = []

    # Use enumerate starting from 1 for 1-based line numbering
    for line_num, line in enumerate(lines, 1):
        line = line.rstrip('\n')
        # Skip empty or whitespace-only lines
        if not line.strip():
            continue

        try:
            record = parse_line(line, fmt)
            records.append(record)
        except ParseError as e:
            # Track 1-based line number for ParseError
            bad_lines.append(line_num)
        except ValueError as e:
            # Track line number for format errors or unsupported formats
            # Though parse_line raises ValueError for unsupported fmt, this handles runtime errors during parsing setup
            bad_lines.append(line_num)
            print(f"Warning: Skipping line {line_num} due to parsing error/format issue: {e}", file=sys.stderr) # Added import sys for robustness, though not strictly required by prompt scope

    return records, bad_lines
